/**
 * РАСКЛАДКА ЗАСТАВКИ — ОБЩИЙ МОДУЛЬ ДЛЯ ВСЕХ ИГР.
 *
 * ===================== ЗАЧЕМ ЭТОТ ФАЙЛ =====================
 * Заставка есть у каждой игры студии, и в каждой она была своя: у Гоблина
 * `introLayout.ts` в его репозитории, у rss — свой почти такой же, у остальных
 * игр — доли окна и клампы. Файлы разъезжались молча: правку «полоса прогресса
 * должна скейлиться» пришлось разносить руками, а планшетный бакет появился
 * только там, где о нём вспомнили.
 *
 * Решение владельца: СХЕМА ЗАСТАВКИ ЕДИНАЯ ДЛЯ ВСЕХ ИГР —
 *   • логотип игры        — сверху по центру;
 *   • ряд плашек фич      — по центру;
 *   • «press anywhere…»   — внизу.
 * Раз схема одна, то и код раскладки обязан быть один, а не копия в каждой игре.
 *
 * ===================== ГРАНИЦА «ОБЩЕЕ / ИГРОВОЕ» =====================
 * ЗДЕСЬ (общее) — СТРУКТУРА И ПРАВИЛА РАСКЛАДКИ:
 *   • типы спек (`IntroElementSpec`, `IntroLayoutTable`, `SplashLayoutTable`);
 *   • правило выбора бакета (`introTableFor`) — landscape / portrait / tablet;
 *   • арифметика «реф-px × scale» (`resolveIntroElement`, `resolveIntroSpine`);
 *   • АЛГОРИТМ РАСКЛАДКИ ПЛАШЕК в ряд и в колонку (`layoutIntroPlates`) —
 *     раньше он был скопирован в `loader.ts` каждой игры;
 *   • нейтральные дефолтные таблицы (`defaultIntroLayouts`) — вертикальный ритм
 *     композиции, не привязанный ни к одной игре.
 *
 * В ИГРЕ (игровое) — ВСЁ, ЧТО ПРО КОНКРЕТНУЮ ИГРУ:
 *   • ассеты: логотип, арт плашек, текстуры надписи;
 *   • ПРОПОРЦИИ плашек (`ratios`) — это свойство АРТА, а не раскладки: у Гоблина
 *     [0.82, 0.939, 0.884], у другой игры будут свои;
 *   • сколько плашек вообще (см. `layoutIntroPlates` — число произвольное);
 *   • предикат планшета: у rss есть планшетный кадр, у Гоблина его нет, и
 *     навязывать его отсюда нельзя (см. `IntroBucketOptions.isTablet`);
 *   • доводочные числа, если игре нужны свои, — через `overrideIntroLayouts`.
 *
 * ЧЕГО ЗДЕСЬ НЕТ И НЕ ДОЛЖНО БЫТЬ: игровых ассетов, игровых чисел, импортов из
 * pixi. Модуль — чистая арифметика над `ScreenState`, как и весь `layout/`.
 * ====================================================================
 */
import { resolvePlacement } from './anchor';
import type { LayoutSpec, Placement } from './anchor';
import type { ScreenState } from './screen';
import { TABLET_ABOVE_ASPECT } from './screen';

/** Спека одного элемента заставки: где стоит и какого размера (всё в реф-px). */
export interface IntroElementSpec {
  /** Якорь и offset — как у любого контрола HUD, читает `resolvePlacement`. */
  readonly layout: LayoutSpec;
  /**
   * Габарит в реф-px активного кадра. Для логотипа и надписей это ШИРИНА, для
   * ряда плашек — общая ВЫСОТА (ширина каждой считается из её пропорции).
   * Высота остальных элементов берётся из пропорции арта или метрик текста.
   */
  readonly size: number;
}

/**
 * ФАЗА 1 — СТУДИЙНЫЙ СПЛЕШ: логотип студии, вордмарк под ним, полоса прогресса.
 *
 * Фаза общая для всех игр студии по определению: это экран ПРО СТУДИЮ, а не про
 * игру. Числа тем не менее живут в таблицах, а не в коде, — иначе игре нечем
 * поправить сплеш, если у неё другой знак (пропорции арта у всех разные).
 */
export interface SplashLayoutTable {
  /** Логотип студии. `size` = ШИРИНА в реф-px; высота из пропорции арта. */
  readonly studioLogo: IntroElementSpec;
  /**
   * Зазор от НИЖНЕЙ КРОМКИ логотипа до ЦЕНТРА вордмарка, реф-px.
   *
   * Почему от кромки, а не собственный якорь у вордмарка: пара «знак + надпись» —
   * это ОДИН блок, и надпись обязана держаться низа логотипа, а не своей доли
   * кадра. Высота логотипа зависит от пропорции арта, поэтому позиция вордмарка
   * считается потребителем от РЕАЛЬНОГО габарита спрайта.
   */
  readonly wordmarkGap: number;
  /**
   * Ширина вордмарка как ДОЛЯ ширины логотипа. Текст вписывается в неё, поэтому
   * пара остаётся единым блоком на любом экране.
   */
  readonly wordmarkWOfLogo: number;
  /** Прогресс-бар: якорь + `size` = ШИРИНА в реф-px. */
  readonly bar: IntroElementSpec;
  /** Толщина бара в реф-px — скейлится тем же множителем, что и ширина. */
  readonly barThickness: number;
  /** ТЕКСТ ФАТАЛЬНОЙ ОШИБКИ. `size` = ширина колонки переноса в реф-px. */
  readonly fail: IntroElementSpec;
  /** Кегль текста ошибки в реф-px — скейлится, а не держится пикселей экрана. */
  readonly failFontSize: number;
}

/** Полная раскладка заставки для ОДНОГО бакета (обе фазы). */
export interface IntroLayoutTable {
  /** ФАЗА 1 — студийный сплеш (логотип студии · вордмарк · прогресс-бар). */
  readonly splash: SplashLayoutTable;
  /** Логотип игры — герой заставки, сверху по центру. `size` = ширина. */
  readonly logo: IntroElementSpec;
  /**
   * Ряд плашек фич — композиционный центр заставки.
   *
   * `size` = общая ВЫСОТА ряда (в колонке — высота ОДНОЙ плашки). Ширина каждой
   * плашки считается из её пропорции, поэтому ряд выравнивается по верхней и
   * нижней кромке независимо от того, какого размера исходники.
   */
  readonly plates: IntroElementSpec;
  /**
   * Зазор МЕЖДУ плашками в реф-px (масштабируется вместе со всем).
   *
   * ЗАЗОР НЕ ДЕКОРАТИВНЫЙ, А ФУНКЦИОНАЛЬНЫЙ, и жать его нельзя. Арт плашки —
   * это не ровный прямоугольник: у Гоблина в `rule*.webp` декор (столб, динамит,
   * кристалл) НАМЕРЕННО ВЫСТУПАЕТ ЗА РАМУ панели и упирается в кромку спрайта.
   * Поставь панели вплотную — выступающий декор соседок сойдётся, а прижатые к
   * краю экрана срежутся вместе с кромкой (ровно этот дефект владелец и увидел
   * у Гоблина). Поэтому зазор задан с запасом на вылет декора, а не «на глаз».
   */
  readonly plateGap: number;
  /**
   * Ряд плашек ставится В КОЛОНКУ, а не в строку. Нужен узкому экрану: три
   * плашки рядом на телефоне ужимаются до нечитаемого.
   */
  readonly stack?: boolean;
  /** «press anywhere to continue» — внизу по центру. `size` = ПОТОЛОК ширины. */
  readonly press: IntroElementSpec;
  /**
   * КЕГЛЬ надписи в реф-px — умножается на `screen.scale`.
   *
   * РАЗМЕР ЗАДАЁТ ИМЕННО КЕГЛЬ, А НЕ `press.size`. Это не мелочь: если размером
   * управляет потолок ширины, то пока надпись уже потолка, её не трогают вовсе —
   * и она держит ОДНИ И ТЕ ЖЕ пиксели на всех вьюпортах подряд, то есть не
   * следует за окном. `press.size` остаётся СТРАХОВКОЙ от переполнения (длинная
   * локализация, очень узкий экран), а не механизмом размера.
   *
   * Игры, у которых надпись — СПРАЙТ, а не текст, кегль просто не читают: им
   * хватает `press.size` как целевой ширины арта.
   */
  readonly pressFontSize: number;
}

/** Раскладка заставки во всех трёх бакетах. */
export interface IntroLayoutTables {
  readonly landscape: IntroLayoutTable;
  readonly portrait: IntroLayoutTable;
  readonly tablet: IntroLayoutTable;
}

/**
 * ЛАНДШАФТ — опорный кадр 1920×1080.
 *
 * ЯКОРЯ ПО СМЫСЛУ ЭЛЕМЕНТА, а не «все от центра» или «все от верха»:
 *   • logo   — `top-center`: висит под верхней кромкой и на низком окне обязан
 *     ехать вместе с ней, а не всплывать из центра;
 *   • plates — `center`: ряд держит середину экрана, это композиционный центр;
 *   • press  — `bottom-center`: прижата к низу, как и весь нижний бар HUD.
 * Разметь их долями высоты — и все трое поехали бы от верха, сходясь друг к
 * другу на низком окне. Ровно это и было в играх до перевода на спеки.
 *
 * ВЕРТИКАЛЬНЫЙ РИТМ ПЕРЕСЧИТАН ПОД ТРЁХЧАСТНУЮ КОМПОЗИЦИЮ, а не унаследован.
 * Раньше в rss центр занимали ПЕРСОНАЖИ, и логотип лежал у их ног — просвет
 * «лого ↔ надпись» выходил 4.6 px by design. Теперь центр отдан плашкам, и
 * ритм считается заново, от содержимого:
 *   логотип 200 (высота при ширине 560 и типичной пропорции ~2.8)
 *   + ряд плашек 360 + надпись ~40 = 600 реф-px содержимого;
 *   свободно 1080 − 600 = 480, то есть по 120 на каждый из четырёх промежутков.
 * Отсюда: logoCY = 120 + 100 = 220; центр ряда = 240 + 200 + 180 = 620 = центр
 * кадра (540) + 80; pressCY = 1080 − 120 + 20 ≈ 1080 − 54.
 */
const introLandscape: IntroLayoutTable = {
  splash: {
    studioLogo: { layout: { anchor: 'center', offset: [0, 0] }, size: 240 },
    wordmarkGap: 24,
    wordmarkWOfLogo: 1.0,
    // 320 реф-px ширины — полоса едет за скейлом целиком, и длина, и толщина.
    // 162 реф-px от нижней кромки = 15% высоты кадра.
    bar: { layout: { anchor: 'bottom-center', offset: [0, -162] }, size: 320 },
    // 12, а не прежние 6: при 6 полоса читалась ВОЛОСКОМ под крупным знаком
    // студии. Скругление подстраивается само — потребитель считает его как
    // `barH / 2` (см. `loader.ts` каждой игры), поэтому торцы остаются
    // полностью круглыми при любой толщине, и менять там нечего.
    barThickness: 12,
    // Колонка 1536 = 80% ширины кадра.
    fail: { layout: { anchor: 'center', offset: [0, 64.8] }, size: 1536 },
    failFontSize: 26,
  },
  logo: { layout: { anchor: 'top-center', offset: [0, 190] }, size: 560 },
  /**
   * ЦЕНТР РЯДА — 40 реф-px НИЖЕ середины кадра, а не 80.
   *
   * Ритм выравнивается по ИЗМЕРЕННЫМ просветам, а не по формуле «поровну»:
   * логотип занимает верх неравномерно (его арт несимметричен в своём кадре),
   * поэтому равные промежутки в спеке дают НЕравные просветы на экране. Замер
   * на опорном кадре при offset 80 давал 36 px сверху ряда против 192 снизу —
   * ряд прижимался к логотипу, а под ним зияла пустота. Подъём логотипа на
   * 190 и ряда на 40 разводит это к 66/152: сверху по-прежнему теснее (так и
   * должно быть — снизу стоит надпись, которой нужен воздух), но композиция
   * читается как три яруса, а не как «лого с плашками» и дыра.
   */
  plates: { layout: { anchor: 'center', offset: [0, 40] }, size: 360 },
  plateGap: 80,
  // Y СТРОГО ПО КНОПКЕ MUTE ландшафта (`landscapeLayout.ts` LEFT_ROW_Y = -120):
  // надпись и кнопка звука стоят на ОДНОЙ линии. Оба якоря — от нижней кромки,
  // поэтому равный offset даёт равный Y центра; у mute якорь bottom-left, у
  // надписи bottom-center, но по вертикали это одна и та же база.
  //
  // Прежние 54 реф-px прижимали надпись к самому краю, ниже линии интерфейса, и
  // на переходе интро → игра нижний ярус заметно подпрыгивал.
  // `size` — ПОТОЛОК ширины, размер задаёт кегль.
  press: { layout: { anchor: 'bottom-center', offset: [0, -120] }, size: 1728 },
  pressFontSize: 34,
};

/**
 * ПЛАНШЕТ — кадр 1080×1440 (3:4 классического iPad).
 *
 * Кадр УЖЕ ландшафтного, поэтому доли берутся крупнее: знак 300/1080 = 28%
 * против 240/1920 = 12.5%. Это не «на глаз», а то же требование — элемент
 * обязан читаться одинаково крупно ОТНОСИТЕЛЬНО ЭКРАНА в любом бакете.
 *
 * Ряд плашек влезает БЕЗ УЖИМАНИЯ по построению: при высоте 360 и трёх типичных
 * пропорциях (~0.88 в среднем) ширина ряда ≈ 360 × 2.64 + 32 × 2 = 1015 из 1080,
 * то есть 94% кадра. Игра с более широкими плашками уменьшает `plates.size` у
 * себя — потолок ширины экрана мы отсюда не знаем и знать не должны.
 *
 * Ритм: логотип 270 + ряд 360 + надпись ~50 = 680; свободно 760, по 190 на
 * промежуток → logoCY = 190 + 135 = 325; центр ряда = 380 + 270 + 180 = 830 =
 * центр кадра (720) + 110; надпись — 225 от нижней кромки.
 */
const introTablet: IntroLayoutTable = {
  splash: {
    studioLogo: { layout: { anchor: 'center', offset: [0, 0] }, size: 300 },
    wordmarkGap: 30,
    wordmarkWOfLogo: 1.0,
    bar: { layout: { anchor: 'bottom-center', offset: [0, -162] }, size: 400 },
    // 16, а не прежние 8 — вдвое, как и в ландшафте. Скругление берётся от
    // толщины (`barH / 2`), торцы остаются круглыми.
    barThickness: 16,
    // Колонка 864 = 80% ширины кадра — та же доля, что в ландшафте. Кегль
    // крупнее ландшафтного: 26 реф-px от 1920 и от 1080 — разная физическая
    // доля, и на узком кадре буква вышла бы мелкой.
    fail: { layout: { anchor: 'center', offset: [0, 86] }, size: 864 },
    failFontSize: 34,
  },
  logo: { layout: { anchor: 'top-center', offset: [0, 325] }, size: 760 },
  /**
   * ВЫСОТА РЯДА ОГРАНИЧЕНА ШИРИНОЙ КАДРА, а не вертикалью: три плашки в ряд при
   * сумме пропорций ~2.64 дают ширину 2.64 × h + 2 зазора. При h = 360 это
   * 360 × 2.64 + 64 = 1015 из 1080 — ряд упирался в кромки (замер на 834×1194:
   * поля по 24.9 px). 320 даёт 320 × 2.64 + 64 = 909 из 1080, то есть поля по
   * 85 реф-px с каждой стороны — ряд дышит и не липнет к краю.
   */
  plates: { layout: { anchor: 'center', offset: [0, 110] }, size: 320 },
  plateGap: 32,
  // Y СТРОГО ПО КНОПКЕ MUTE планшета (`tabletLayout.ts` ROW_Y = -170) — надпись
  // и круглая кнопка звука на одной линии, центр в центр. Было 225.
  press: { layout: { anchor: 'bottom-center', offset: [0, -170] }, size: 972 },
  pressFontSize: 44,
};

/**
 * ТЕЛЕФОН — портретный кадр 1080×2337.
 *
 * ПЛАШКИ В КОЛОНКУ (`stack`). Три в ряд на телефоне физически не читаются: кадр
 * узкий, и ряд пришлось бы ужимать втрое — текст на плашке превращается в
 * серую кашу. Кадр при этом ВЫСОКИЙ (аспект 0.46): вертикали вдоволь, ширины
 * нет, поэтому колонка — та же композиция, повёрнутая в доступное измерение.
 *
 * Ширина плашки в колонке считается из её пропорции: при высоте 460 и типичной
 * пропорции ~0.9 это ~414 реф-px из 1080, то есть по ширине колонка не упирается.
 *
 * БАР ОТСЧИТЫВАЕТСЯ ОТ НИЖНЕЙ КРОМКИ, но отступ СВОЙ — 350 реф-px, а не
 * ландшафтные 162: на кадре высотой 2337 те 162 были бы 6.9% высоты против 15%
 * в ландшафте, то есть полоса прилипла бы к самому краю. 350/2337 = 15% — та же
 * доля, что и в ландшафте.
 */
const introPortrait: IntroLayoutTable = {
  splash: {
    studioLogo: { layout: { anchor: 'center', offset: [0, 0] }, size: 340 },
    wordmarkGap: 34,
    wordmarkWOfLogo: 1.0,
    bar: { layout: { anchor: 'bottom-center', offset: [0, -350] }, size: 440 },
    // 28, а не прежние 9. Прибавка ТУТ БОЛЬШЕ, чем в других кадрах (12 из 6,
    // 16 из 8), потому что у телефона самый мелкий скейл: на 390×844 он ~0.36,
    // и 9 реф-px давали на экране 3.2 px — не полоса, а волосок. 28 дают ~10 px.
    // Скругление считается потребителем как `barH / 2`, торцы остаются круглыми.
    barThickness: 28,
    fail: { layout: { anchor: 'center', offset: [0, 140] }, size: 864 },
    failFontSize: 34,
  },
  // Ширина 880 из 1080 кадра — знак на телефоне взят крупно в долях ширины,
  // иначе на 390 px экрана он читался бы марочкой.
  logo: { layout: { anchor: 'top-center', offset: [0, 300] }, size: 880 },
  /**
   * В КОЛОНКЕ `size` — высота ОДНОЙ плашки, и она выведена ИЗ КОРИДОРА, а не
   * взята на глаз. Коридор считается между реальными кромками соседей:
   *   низ логотипа  ≈ 550 реф-px (якорь 300 + полувысота арта);
   *   верх надписи  ≈ 2337 − 180 − 40 = 2117 реф-px;
   *   свободно      ≈ 1567, минус два зазора по 44 = 1479 на три плашки.
   * Отсюда высота одной ≈ 1479 / 3 = 493, и берём 380 — с запасом, чтобы
   * коридор закрывался с полями, а не впритык: колонка из трёх плашек занимает
   * 380 × 3 + 44 × 2 = 1228 реф-px, оставляя по ~170 сверху и снизу.
   *
   * ПОЧЕМУ НЕ БОЛЬШЕ. Прежние 460 давали колонку в 1468 реф-px, и на живом
   * телефоне 390×844 (scale 0.361) она наезжала на логотип: замер дал просвет
   * −11.7 px, то есть арт лёг НА знак. Высота колонки — это ровно та величина,
   * которую нельзя подбирать «покрупнее»: у телефона вертикаль конечна.
   */
  plates: { layout: { anchor: 'center', offset: [0, 120] }, size: 380 },
  plateGap: 44,
  stack: true,
  // Y СТРОГО ПО КНОПКЕ MUTE портрета (`defaultLayouts.ts`, mute offset
  // [96, -220]) — надпись и круглая кнопка звука на одной линии. Было 180.
  press: { layout: { anchor: 'bottom-center', offset: [0, -220] }, size: 972 },
  pressFontSize: 44,
};

/**
 * НЕЙТРАЛЬНЫЕ ДЕФОЛТНЫЕ ТАБЛИЦЫ — стартовая точка для любой игры.
 *
 * Игре не обязано подходить всё: пропорции её логотипа и плашек мы не знаем.
 * Поэтому числа заданы так, чтобы КОМПОЗИЦИЯ была верной (логотип сверху, ряд
 * по центру, надпись внизу, ритм разложен по кадру), а доводку игра делает
 * через `overrideIntroLayouts` — точечно и с обоснованием у себя.
 */
export const defaultIntroLayouts: IntroLayoutTables = {
  landscape: introLandscape,
  portrait: introPortrait,
  tablet: introTablet,
};

/**
 * Как игра отвечает на вопрос «это планшет?».
 *
 * ПРЕДИКАТ ОБЯЗАН БЫТЬ ТОТ ЖЕ, ЧТО У HUD ЭТОЙ ИГРЫ. Разъедутся они — заставка и
 * интерфейс выберут разные бакеты на границе, и переход интро → игра прыгнет.
 * Поэтому предикат ПРИХОДИТ ИЗ ИГРЫ, а не решается здесь: у rss планшетный кадр
 * есть (`isTabletLayout` из её `tabletLayout.ts`), у Гоблина его нет вовсе, и
 * навязать ему планшетный бакет отсюда значило бы сломать ему раскладку.
 */
export interface IntroBucketOptions {
  /**
   * Предикат планшета. Не задан — планшетный бакет НЕ ИСПОЛЬЗУЕТСЯ, и широкий
   * портрет считается телефонным, как было до появления `refTablet`. Именно это
   * делает модуль обратно совместимым с играми без планшетной раскладки.
   */
  readonly isTablet?: (screen: ScreenState) => boolean;
}

/**
 * Дефолтный предикат планшета — по АСПЕКТУ, тем же порогом, что `computeScreen`
 * выбирает планшетный КАДР (`TABLET_ABOVE_ASPECT`).
 *
 * Кадр и таблица обязаны решаться одним критерием: выбери их по-разному — и
 * оффсеты, размеченные в планшетном кадре, применятся в шкале телефонного.
 * Игра, у которой уже есть свой `isTabletLayout`, передаёт ЕГО, а не этот.
 */
export function isTabletScreen(screen: ScreenState): boolean {
  return screen.orientation === 'portrait' && screen.width / screen.height >= TABLET_ABOVE_ASPECT;
}

/**
 * Таблица заставки для ТЕКУЩЕГО экрана.
 *
 * Порядок ветвления тот же, что у HUD: планшет проверяется ПЕРВЫМ, потому что
 * планшет — это тоже портрет, и проверь мы ориентацию раньше, планшетная ветка
 * была бы недостижима.
 */
export function introTableFor(
  screen: ScreenState,
  tables: IntroLayoutTables = defaultIntroLayouts,
  opts: IntroBucketOptions = {},
): IntroLayoutTable {
  if (opts.isTablet?.(screen)) return tables.tablet;
  if (screen.orientation === 'portrait') return tables.portrait;
  return tables.landscape;
}

/** Точечная правка таблиц: `{ landscape: { plateGap: 64 } }` и т.п. */
export type IntroLayoutOverrides = {
  readonly [B in keyof IntroLayoutTables]?: Partial<IntroLayoutTable>;
};

/**
 * Наложить правки игры на базовые таблицы — поверхностно, по бакетам.
 *
 * Зачем отдельная функция, а не спред по месту: спред руками легко сделать
 * НЕПОЛНЫМ (забыть бакет) или, наоборот, затереть вложенный `splash` целиком.
 * Здесь оба риска закрыты: бакеты перечислены явно, `splash` мержится отдельно.
 */
export function overrideIntroLayouts(
  base: IntroLayoutTables,
  overrides: IntroLayoutOverrides,
): IntroLayoutTables {
  const merge = (table: IntroLayoutTable, patch?: Partial<IntroLayoutTable>): IntroLayoutTable =>
    patch ? { ...table, ...patch, splash: { ...table.splash, ...(patch.splash ?? {}) } } : table;
  return {
    landscape: merge(base.landscape, overrides.landscape),
    portrait: merge(base.portrait, overrides.portrait),
    tablet: merge(base.tablet, overrides.tablet),
  };
}

/** Итоговая геометрия одного элемента заставки в ПИКСЕЛЯХ ЭКРАНА. */
export interface IntroPlacement extends Placement {
  /** Габарит элемента в px экрана (реф-размер × screen.scale). */
  size: number;
}

/**
 * Позиция и размер элемента заставки — `resolvePlacement` плюс размер в той же
 * шкале. Отдельной функцией, чтобы потребитель не собирал эту пару руками для
 * каждого элемента и не мог случайно взять разный скейл для позиции и размера.
 */
export function resolveIntroElement(spec: IntroElementSpec, screen: ScreenState): IntroPlacement {
  const p = resolvePlacement(spec.layout, screen);
  return { ...p, size: spec.size * screen.scale };
}

/**
 * Элемент SPINE-СЦЕНЫ заставки: позиция плюс ГОТОВЫЙ МНОЖИТЕЛЬ СКЕЛЕТА.
 *
 * Отдельно от `resolveIntroElement`, потому что у скелета размер задаётся не
 * шириной спрайта, а `scale.set(k)` относительно АВТОРСКОГО КАДРА. Считать это
 * делением по месту в игре — значит снова развести две шкалы.
 */
export interface IntroSpinePlacement {
  /** Позиция якоря в px экрана. */
  x: number;
  y: number;
  /** Множитель для `spine.scale.set()`. */
  k: number;
}

/**
 * Позиция и множитель Spine-элемента заставки.
 *
 * ЯКОРЬ СЧИТАЕТСЯ ОТ ПРЯМОУГОЛЬНИКА ЭКРАНА, а не от stage. Сегодня `stage`
 * растянут на весь экран и это одно и то же, но у декора якорь к КРОМКЕ ЭКРАНА —
 * часть его определения: фигура стоит у края физического экрана, а не у края
 * расчётного кадра. Подмена делает это независимым от того, вернётся ли
 * когда-нибудь letterbox в stage.
 *
 * `frameUnits` — габарит авторского кадра скелета в его собственных юнитах.
 */
export function resolveIntroSpine(
  spec: IntroElementSpec,
  screen: ScreenState,
  frameUnits: number,
): IntroSpinePlacement {
  const screenAsStage: ScreenState = {
    ...screen,
    stage: { x: 0, y: 0, width: screen.width, height: screen.height },
  };
  const p = resolvePlacement(spec.layout, screenAsStage);
  return { x: p.x, y: p.y, k: (spec.size * screen.scale) / frameUnits };
}

/** Прямоугольник одной плашки в px экрана — то, что игра ставит спрайту. */
export interface IntroPlateBox {
  /** Центр плашки. */
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * РАСКЛАДКА РЯДА ПЛАШЕК — ряд или колонка, ПРОИЗВОЛЬНОЕ ЧИСЛО ПЛАШЕК.
 *
 * ===================== ПОЧЕМУ ЭТО ЗДЕСЬ, А НЕ В ИГРЕ =====================
 * Этот цикл был скопирован в `loader.ts` каждой игры — вместе с обеими ветками
 * (ряд/колонка), центрированием по курсору и умножением зазора на скейл. Это
 * ПРАВИЛО РАСКЛАДКИ, а не свойство игры: игра отличается только тем, СКОЛЬКО у
 * неё плашек и какие у них пропорции. Оба различия — аргументы, а не код.
 * ========================================================================
 *
 * ЧИСЛО ПЛАШЕК ПРОИЗВОЛЬНОЕ, включая НОЛЬ. Пустой `ratios` возвращает пустой
 * массив, и заставка остаётся рабочей: логотип сверху, надпись внизу, центр
 * пуст. Это не вырожденный случай «на всякий случай», а штатный режим игры,
 * которой арт плашек ещё не приехал, — композиция при его появлении не
 * пересчитывается, потому что ритм задан таблицей, а не содержимым.
 *
 * `ratios` — ШИРИНА / ВЫСОТА каждой плашки, в порядке отрисовки. Высота у ряда
 * ОБЩАЯ (из спеки), ширина у каждой своя — так строка выравнивается по верхней
 * и нижней кромке независимо от размеров исходников.
 */
export function layoutIntroPlates(
  table: IntroLayoutTable,
  screen: ScreenState,
  ratios: readonly number[],
): IntroPlateBox[] {
  if (ratios.length === 0) return [];
  const p = resolveIntroElement(table.plates, screen);
  const gap = table.plateGap * screen.scale;
  const height = p.size;
  const widths = ratios.map((r) => height * r);
  if (table.stack) {
    // КОЛОНКА: у каждой плашки своя ширина, поэтому по X центрируем каждую
    // отдельно, а по Y раскладываем стопкой от верхней кромки блока.
    const totalH = height * ratios.length + gap * (ratios.length - 1);
    let cursorY = p.y - totalH / 2;
    return widths.map((width) => {
      const box: IntroPlateBox = { x: p.x, y: cursorY + height / 2, width, height };
      cursorY += height + gap;
      return box;
    });
  }
  // РЯД: общая высота, ширина у каждой своя; строка центрируется по точке из
  // `resolvePlacement`, поэтому композиционный центр задаёт ЯКОРЬ, а не
  // подобранная доля окна.
  const totalW = widths.reduce((sum, x) => sum + x, 0) + gap * (widths.length - 1);
  let cursorX = p.x - totalW / 2;
  return widths.map((width) => {
    const box: IntroPlateBox = { x: cursorX + width / 2, y: p.y, width, height };
    cursorX += width + gap;
    return box;
  });
}
